SELECT thread_id,checkpoint_id,source_revision,through_ordinal,retained_from_ordinal,retained_split_json,summary_json,
  input_tokens,envelope_fingerprint,strategy_version,usage_json,created_at FROM context_checkpoints WHERE thread_id=#{threadId}
ORDER BY source_revision DESC LIMIT 1

SELECT thread_id,checkpoint_id,source_revision,through_ordinal,retained_from_ordinal,retained_split_json,summary_json,
  input_tokens,envelope_fingerprint,strategy_version,usage_json,created_at FROM context_checkpoints
WHERE thread_id=#{threadId} AND source_revision=#{sourceRevision}
